// Загрузчик поискового индекса: темы курса, термины глоссария, бизнес-метрики.
//
// Индекс собирается при сборке (vite.config.js), а не в рантайме: искать по
// самим урокам значило бы тянуть ~865 KB курса и ~350 KB каталога метрик ради
// подсказок в строке поиска.
//
// Локали лежат в отдельных файлах и грузятся отдельными чанками — вместе они
// дают около 44 KB gzip, а посетителю нужна ровно одна. Сюда же приходит
// первое обращение к поиску: до открытия окна не грузится ничего.
export async function loadSearchIndex(locale) {
  const m = locale === 'en'
    ? await import('./searchIndex.en.js')
    : await import('./searchIndex.ru.js')
  return m.index
}
